"""Table-based HTML email with escaped data and a plain-text alternative."""
from datetime import datetime,timezone,timedelta
from html import escape
import socket
from zoneinfo import ZoneInfo,ZoneInfoNotFoundError

def local_time(timestamp,zone='Asia/Shanghai'):
    try:tz=ZoneInfo(zone)
    except ZoneInfoNotFoundError:tz=timezone(timedelta(hours=8))
    return datetime.fromtimestamp(timestamp,tz).strftime('%Y-%m-%d %H:%M:%S')+' (UTC'+datetime.fromtimestamp(timestamp,tz).strftime('%z')[:3]+')'

def render(items,hostname=None,zone='Asia/Shanghai'):
    hostname=hostname or socket.gethostname()
    triggered=sum(i['state']=='触发' for i in items);recovered=sum(i['state']=='恢复' for i in items)
    test=all(i['state']=='测试' for i in items)
    title='邮箱告警已就绪' if test else '服务状态已恢复' if recovered and not triggered else '监控节点需要关注'
    subtitle='一封更清晰的监控通知，从这里开始。' if test else '以下为本次合并的状态变化，请根据指标判断是否需要处理。'
    badge='连接测试' if test else '已恢复' if recovered and not triggered else '告警通知'
    accent='#b6f171' if test or not triggered else '#ffc278'
    rows=[]
    for item in items:
        state=item['state'];color='#326b4b' if state=='恢复' else '#2c5379' if state=='测试' else '#9f4a20'
        bg='#eaf5ed' if state=='恢复' else '#edf4fb' if state=='测试' else '#fff1e5'
        level='正常' if state=='恢复' else '严重' if item['level']=='critical' else '注意' if item['level']=='warning' else '信息'
        rows.append(f'''<tr><td style="padding:0 30px 16px" class="pad"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e3e8ec;border-radius:12px;background:#ffffff"><tr><td style="padding:20px 22px;border-left:4px solid {color};border-radius:10px"><table role="presentation" width="100%"><tr><td><span style="display:inline-block;padding:4px 9px;border-radius:5px;background:{bg};color:{color};font-size:11px;font-weight:bold">{escape(state)} · {escape(level)}</span></td><td align="right" style="font-size:11px;color:#8b96a3">LOCAL MONITOR</td></tr></table><h2 style="font-size:17px;line-height:1.5;margin:15px 0 10px;color:#172332">{escape((item.get('target','')+' · ' if item.get('target') else '')+item['title'])}</h2><div style="font-size:14px;line-height:1.85;color:#536174;word-break:break-word">{escape(item['detail']).replace(chr(10),'<br>')}</div><div style="border-top:1px solid #edf0f3;margin-top:18px;padding-top:12px;color:#82909e;font-size:11px;line-height:1.7">{escape(local_time(item['time'],zone))}</div></td></tr></table></td></tr>''')
    html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>@media(max-width:600px){{.outer{{padding:16px 8px!important}}.pad{{padding-left:20px!important;padding-right:20px!important}}.headline{{font-size:25px!important}}}}</style></head><body style="margin:0;padding:0;background:#edf1f4;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',Arial,sans-serif;color:#172332"><div style="display:none;max-height:0;overflow:hidden;opacity:0">{escape(title)} · {len(items)} 条状态更新 · {escape(hostname)}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#edf1f4"><tr><td align="center" class="outer" style="padding:36px 16px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#f8fafb;border:1px solid #dde4e9;border-radius:18px;overflow:hidden"><tr><td class="pad" style="padding:30px;background:#17212c;border-bottom:4px solid {accent}"><table role="presentation" width="100%"><tr><td style="color:#e8f1f8;font-size:18px;font-weight:bold;letter-spacing:-.5px"><span style="color:#b6f171">◈</span> Local Services</td><td align="right"><span style="color:{accent};font-size:11px;border:1px solid #465445;border-radius:5px;padding:5px 9px">{badge}</span></td></tr></table><h1 class="headline" style="margin:30px 0 10px;font-size:30px;line-height:1.35;letter-spacing:-1px;color:#ffffff">{title}</h1><p style="margin:0;color:#aab7c5;font-size:13px;line-height:1.9">{subtitle}</p><p style="margin:20px 0 0;font-size:11px;color:#8d9cac">设备 · {escape(hostname)}</p></td></tr><tr><td class="pad" style="padding:26px 30px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="33%" style="border-right:1px solid #e1e7ed"><div style="font-size:11px;color:#84909e">本次通知</div><div style="font-size:28px;line-height:1.7;font-weight:bold;color:#223247">{len(items)}<span style="font-size:12px;font-weight:normal;color:#8b96a3"> 条</span></div></td><td width="33%" style="padding-left:23px;border-right:1px solid #e1e7ed"><div style="font-size:11px;color:#84909e">触发告警</div><div style="font-size:28px;line-height:1.7;font-weight:bold;color:#b56431">{triggered}</div></td><td width="33%" style="padding-left:23px"><div style="font-size:11px;color:#84909e">恢复正常</div><div style="font-size:28px;line-height:1.7;font-weight:bold;color:#417755">{recovered}</div></td></tr></table></td></tr>{''.join(rows)}<tr><td class="pad" style="padding:8px 30px 28px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-radius:10px;background:#eaf0f5"><tr><td style="padding:18px 20px"><div style="font-size:12px;font-weight:bold;color:#40536b">下一步</div><p style="font-size:12px;line-height:1.9;color:#667a90;margin:8px 0 0">{'收到此信说明 SMTP 服务器已接受测试投递。后续通知将在告警触发与恢复时发送。' if test else '查看资源排行与服务日志，确认持续高占用或服务离线的原因。若已恢复，可在告警中心查看记录。'}<br>在被监控设备上打开本地面板，即可查看实时指标。</p></td></tr></table></td></tr><tr><td align="center" class="pad" style="border-top:1px solid #e1e7ed;padding:22px 30px;color:#91a0af;font-size:10px;line-height:1.9">Local Services · 本机服务与资源监控<br>自动通知 · 持续告警合并去重 · 恢复后单独提醒<br>时间显示为 Asia/Shanghai（UTC+8）</td></tr></table></td></tr></table></body></html>'''
    plain=[title,'设备：'+hostname,'']
    for i in items:plain.extend([f"[{i['state']}] {i['title']}",local_time(i['time'],zone),i['detail'],''])
    return html,'\n'.join(plain)
